    return sum(numbers) / len(numbers)


def average(numbers):
    if not numbers:
        return 0
    return sum(numbers) / len(numbers)


def check_empty(avg):
    assert avg([]) == 0


def verdict(check, impl):
    try:
        check(impl)
        return "PASS"
    except Exception:
        return "FAIL"


print("до исправления:", verdict(check_empty, buggy_average))
print("после исправления:", verdict(check_empty, average))

